package com.procurement.rfq.mapper; import com.procurement.rfq.dto.response.*; import com.procurement.rfq.entity.*; import org.springframework.stereotype.Component; @Component public class RfqMapper{public RfqResponse toResponse(Rfq e){return new RfqResponse(e.getId(),e.getRfqNumber(),e.getPurchaseRequest().getId(),e.getPurchaseRequest().getRequestNumber(),e.getPurchaseRequest().getDepartment().getId(),e.getPurchaseRequest().getDepartment().getDepartmentName(),e.getIssueDate(),e.getClosingDate(),e.getQuotationOpeningDate(),e.getCurrency(),e.getStatus(),e.getRemarks(),e.getCreatedBy(),e.getUpdatedBy(),e.getCreatedAt(),e.getUpdatedAt());}public RfqLineResponse toLineResponse(RfqLine e){return new RfqLineResponse(e.getId(),e.getRfq().getId(),e.getProduct().getId(),e.getProduct().getProductCode(),e.getProduct().getProductName(),e.getQuantity(),e.getRequiredDate(),e.getEstimatedUnitPrice(),e.getRemarks());}public RfqVendorResponse toVendorResponse(RfqVendor e){return new RfqVendorResponse(e.getId(),e.getRfq().getId(),e.getVendor().getId(),e.getVendor().getVendorCode(),e.getVendor().getVendorName(),e.getInvitationDate(),e.getResponseStatus(),e.getResponseDate(),e.getRemarks());}}
